('ar-s01','ar','story','stories','الأرنب والجزرة','1f430',array['a3','a4']::text[],'القراءة وفهم المقروء',$j${"pages": [{"t": "أرنب صغير اسمه نونو. نونو جائع.", "img": "1f430"}, {"t": "رأى نونو جزرة كبيرة تحت الشجرة.", "img": "1f955"}, {"t": "أكل نونو الجزرة. شبع نونو وفرح.", "img": "1f604"}], "vocab": [["جائع", "يريد أن يأكل"], ["الشجرة", "نبات كبير له جذع وأوراق"], ["شبع", "لم يعد يريد الأكل"]], "qs": [{"q": "ماذا رأى نونو؟", "o": ["جزرة كبيرة", "كرة حمراء", "كتابا جديدا"], "a": 0}, {"q": "أين كانت الجزرة؟", "o": ["تحت الشجرة", "فوق البيت", "في الماء"], "a": 0}, {"q": "كيف أصبح نونو في النهاية؟", "o": ["فرحا", "حزينا", "غاضبا"], "a": 0}], "events": ["نونو جائع", "رأى نونو جزرة", "أكل نونو الجزرة"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',200),
