('ar-s03','ar','story','stories','علي والمطر','1f327',array['a5','a6','g1','g2']::text[],'القراءة وفهم المقروء',$j${"pages": [{"t": "استيقظ علي صباحا فرأى المطر ينزل من السماء.", "img": "1f327"}, {"t": "أخذ علي مظلته الزرقاء وذهب إلى المدرسة.", "img": "1f392"}, {"t": "في الطريق توقف المطر وخرجت الشمس.", "img": "2600"}, {"t": "ظهر في السماء قوس قزح جميل بألوان كثيرة، ففرح علي كثيرا.", "img": "1f308"}], "vocab": [["مظلة", "شيء نفتحه فوق رؤوسنا لنحتمي من المطر"], ["توقف", "لم يعد ينزل"], ["قوس قزح", "ألوان جميلة تظهر في السماء بعد المطر"]], "qs": [{"q": "ماذا أخذ علي إلى المدرسة؟", "o": ["مظلة زرقاء", "كرة حمراء", "قبعة صفراء"], "a": 0}, {"q": "متى خرجت الشمس؟", "o": ["بعد أن توقف المطر", "قبل الصباح", "في الليل"], "a": 0}, {"q": "ماذا ظهر في السماء؟", "o": ["قوس قزح", "طائرة صغيرة", "ثلج أبيض"], "a": 0}, {"q": "لماذا فرح علي؟", "o": ["لأنه رأى قوس قزح جميلا", "لأنه وجد لعبة", "لأن المدرسة أغلقت"], "a": 0}], "events": ["استيقظ علي ورأى المطر", "أخذ علي مظلته وذهب", "توقف المطر", "ظهر قوس قزح"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',202),
