('ar-s05','ar','story','stories','حديقة المدرسة','1f331',array['g3','g4']::text[],'القراءة وفهم المقروء',$j${"pages": [{"t": "قررت معلمة الصف الثالث أن يزرع التلاميذ حديقة صغيرة في ساحة المدرسة.", "img": "1f331"}, {"t": "وزعت المعلمة المهام: حفرت ليلى التراب، ووضع سالم البذور، وسقى حمد الماء كل صباح.", "img": "1f4a7"}, {"t": "مرت أسابيع وهم ينتظرون بصبر، وفي يوم من الأيام ظهرت براعم خضراء صغيرة.", "img": "1f33f"}, {"t": "كبرت النباتات وتفتحت الأزهار الملونة، فعرف التلاميذ أن التعاون والصبر يصنعان الجمال.", "img": "1f33b"}], "vocab": [["وزعت", "أعطت كل واحد نصيبه"], ["براعم", "أوراق وأزهار صغيرة تبدأ بالظهور"], ["التعاون", "أن يعمل الجميع معا"], ["بصبر", "دون استعجال أو ضجر"]], "qs": [{"q": "من وضع البذور؟", "o": ["سالم", "ليلى", "حمد"], "a": 0}, {"q": "ماذا كان يفعل حمد كل صباح؟", "o": ["يسقي النباتات", "يحفر التراب", "يقطف الأزهار"], "a": 0}, {"q": "ماذا ظهر بعد أسابيع؟", "o": ["براعم خضراء صغيرة", "ثمار كبيرة", "ثلج أبيض"], "a": 0}, {"q": "ما الدرس الذي تعلمه التلاميذ؟", "o": ["التعاون والصبر يصنعان الجمال", "الأقوى يفوز دائما", "الكسل أفضل من العمل"], "a": 0}], "events": ["قررت المعلمة زراعة حديقة", "وزعت المعلمة المهام", "ظهرت البراعم الخضراء", "تفتحت الأزهار الملونة"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',204),
('ar-s06','ar','story','stories','طائرة يوسف الورقية','1f9d2',array['g3','g4']::text[],'القراءة وفهم المقروء',$j${"pages": [{"t": "صنع يوسف طائرة ورقية حمراء بمساعدة جده، وكتب اسمه على ذيلها.", "img": "1f9d2"}, {"t": "في اليوم التالي هبت رياح قوية، فركض يوسف إلى التلة وأطلق طائرته.", "img": "1f4a8"}, {"t": "ارتفعت الطائرة عاليا حتى صارت قرب السحب، لكن الخيط انقطع فجأة.", "img": "2601"}, {"t": "حزن يوسف قليلا، ثم قال له جده: لا بأس، سنصنع طائرة أجمل. فابتسم يوسف وبدأ العمل من جديد.", "img": "1f60a"}], "vocab": [["ذيل", "الجزء الذي يتدلى من خلف الشيء"], ["هبت", "تحركت وانتشرت وهذا يقال للرياح"], ["انقطع", "انفصل وانكسر"], ["فجأة", "دون أن نتوقع"]], "qs": [{"q": "من ساعد يوسف في صنع الطائرة؟", "o": ["جده", "أخوه", "معلمه"], "a": 0}, {"q": "ما لون الطائرة؟", "o": ["حمراء", "زرقاء", "خضراء"], "a": 0}, {"q": "ماذا حدث للخيط؟", "o": ["انقطع", "التف حول الشجرة", "بقي قويا"], "a": 0}, {"q": "ماذا فعل يوسف في النهاية؟", "o": ["بدأ يصنع طائرة جديدة", "ترك اللعب نهائيا", "بكى طويلا"], "a": 0}], "events": ["صنع يوسف الطائرة", "أطلق يوسف الطائرة على التلة", "انقطع الخيط", "بدأ يوسف عملا جديدا"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',205),
