('en-s03','en','story','stories','A Rainy Day','1f327',array['a5','a6','g1','g2']::text[],'قراءة قصة إنجليزية قصيرة وفهمها',$j${"pages": [{"t": "It is a rainy morning. Lina takes her umbrella and walks to school.", "img": "1f327"}, {"t": "She sees a little bird under a tree. The bird is wet and cold.", "img": "1f426"}, {"t": "Lina opens her umbrella over the bird until the rain stops.", "img": "1f60a"}, {"t": "Then the sun comes out and the bird flies away. Lina smiles all day.", "img": "2600"}], "vocab": [["umbrella", "مظلة"], ["wet", "مبلل"], ["until", "حتى"], ["smiles", "تبتسم"]], "qs": [{"q": "How is the weather in the morning?", "o": ["rainy", "sunny", "snowy"], "a": 0}, {"q": "Where is the bird?", "o": ["under a tree", "in a house", "on a bus"], "a": 0}, {"q": "What does Lina do for the bird?", "o": ["She opens her umbrella over it", "She gives it a toy", "She takes it to school"], "a": 0}, {"q": "What happens at the end?", "o": ["The sun comes out", "It starts to snow", "The bus arrives"], "a": 0}], "events": ["Lina walks to school", "She sees a wet bird", "She covers the bird with her umbrella", "The sun comes out"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',202),
