('en-s05','en','story','stories','The Lost Key','1f511',array['g3','g4']::text[],'قراءة قصة إنجليزية قصيرة وفهمها',$j${"pages": [{"t": "On Friday afternoon, Huda could not find her house key. She looked in her bag, but it was not there.", "img": "1f511"}, {"t": "She thought carefully and remembered that she was playing in the yard after school.", "img": "1f50d"}, {"t": "She walked back to the yard and found the key under a small bench.", "img": "1f333"}, {"t": "Huda learned an important lesson. Always put important things in the same place.", "img": "1f4a1"}], "vocab": [["afternoon", "بعد الظهر"], ["carefully", "بانتباه"], ["remembered", "تذكرت"], ["lesson", "درس"]], "qs": [{"q": "When did Huda lose her key?", "o": ["On Friday afternoon", "On Monday morning", "At night"], "a": 0}, {"q": "Where did she look first?", "o": ["In her bag", "Under her bed", "In the kitchen"], "a": 0}, {"q": "Where did she find the key?", "o": ["Under a small bench", "In the car", "In a shoe"], "a": 0}, {"q": "What did Huda learn?", "o": ["Put important things in the same place", "Never go to the yard", "Always lose things"], "a": 0}], "events": ["Huda cannot find her key", "She remembers the yard", "She finds the key under a bench", "She learns a lesson"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',204),
('en-s06','en','story','stories','A Trip to the Sea','1f3dd',array['g3','g4']::text[],'قراءة قصة إنجليزية قصيرة وفهمها',$j${"pages": [{"t": "Last Saturday, Nasser and his family went to the beach by car. The journey took one hour.", "img": "1f697"}, {"t": "Nasser built a big sand castle, and his sister collected colorful shells.", "img": "1f3dd"}, {"t": "In the afternoon, they saw a small boat far away on the blue water.", "img": "1f6a2"}, {"t": "Before going home, the family collected the rubbish. They wanted to keep the beach clean.", "img": "1f60a"}], "vocab": [["beach", "شاطئ"], ["shells", "أصداف"], ["rubbish", "نفايات"], ["journey", "رحلة"]], "qs": [{"q": "How did the family go to the beach?", "o": ["by car", "by bus", "by plane"], "a": 0}, {"q": "What did Nasser build?", "o": ["a sand castle", "a boat", "a house"], "a": 0}, {"q": "What did his sister collect?", "o": ["colorful shells", "small fish", "old toys"], "a": 0}, {"q": "Why did they collect the rubbish?", "o": ["to keep the beach clean", "to take it home as a gift", "because it was a game"], "a": 0}], "events": ["The family goes to the beach", "Nasser builds a sand castle", "They see a small boat", "They collect the rubbish"]}$j$::jsonb,'كُتبت القصة برمجيًا بصياغة أصلية للفئة العمرية، وفُحصت بنيتها آليًا (الإجابات والخيارات والأحرف وورود المفردات في النص). الصور من رسوم المنصة الأصلية وهي رموز توضيحية للمشهد. لم يراجعها معلم لغة متخصص بعد.',true,'published',205)
